use super::{native_layer8_callback_study as l,native_layer8_callback_study_tests as first,native_roof_callback_study_tests as native,native_appearance_replay_study_tests as fixture,native_appearance_inspection as a,native_action_inspection::{NativeActionSnapshot,CatalogPins},native_resources as r};
use std::{fs,path::{Path,PathBuf},sync::atomic::AtomicBool};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn sha(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}fn digest(s:&str)->[u8;32]{(0..32).map(|i|u8::from_str_radix(&s[i*2..i*2+2],16).unwrap()).collect::<Vec<_>>().try_into().unwrap()}fn byte_pin(v:&Value)->r::BytePin{r::BytePin{bytes:v["bytes"].as_u64().unwrap(),sha256:digest(v["sha256"].as_str().unwrap())}}fn pin(path:&Path)->Value{let bytes=fs::read(path).unwrap();json!({"path":path,"bytes":bytes.len(),"sha256":sha(&bytes)})}
pub(super) fn effect(plan:&r::NativeAssetPlan,extra:&mut Vec<Value>)->NativeActionSnapshot{
 let project=Path::new(env!("CARGO_MANIFEST_DIR"));let pointer=project.join("logs/continuation-20261003/r429-catalog-snapshot.json");let s:Value=serde_json::from_slice(&fs::read(&pointer).unwrap()).unwrap();let root=PathBuf::from(s["root"].as_str().unwrap());let pins=s["pins"].as_array().unwrap();let catalog=CatalogPins{index:byte_pin(pins.iter().find(|v|v["name"]=="LTtext.idx").unwrap()),pak:byte_pin(pins.iter().find(|v|v["name"]=="LTtext.pak").unwrap()),decoded_catalog:r::BytePin{bytes:s["reference_bytes"].as_u64().unwrap(),sha256:digest(s["reference_sha256"].as_str().unwrap())}};
 let p:Value=serde_json::from_slice(&fs::read(project.join("target/r425-native-dm564-fixture/consumer-input.json")).unwrap()).unwrap();let sprite=PathBuf::from(p["archive_pins"][2]["path"].as_str().unwrap()).parent().unwrap().to_owned();let effect=NativeActionSnapshot::load_firepot(plan,&root,&sprite,catalog,38,&AtomicBool::new(false)).unwrap();extra.push(pin(&pointer));for n in ["LTtext.idx","LTtext.pak","decoded-LTlist.spr"]{extra.push(pin(&root.join(n)));}let member=project.join("target/r454-layer8-source-input/38-0.spr");assert_eq!(digest(&sha(&fs::read(&member).unwrap())),effect.sprite_sha256());extra.push(pin(&member));effect
}
pub(super) fn continuation(at:u32,queued:bool)->l::ContinueInputs{let mut input=first::input();input.dispatch_ms=Some(at);input.scheduler_sample_ms=Some(at);input.queue_before_pop=Some(usize::from(queued));l::ContinueInputs{callback:input,ordinary_path_reached:Some(true),actor_counter50:Some(0),idle_queue_append_succeeds:Some(true),idle_table_pointer_present:Some(true),post_frame_event_bit:Some(false)}}
#[test]#[ignore = "requires: local evidence roots (snapshot JSON holds absolute D:\\ paths + SHA pins; only runnable on the original machine)"] fn actual_firepot_cycle_end_source_requeue_repeat_and_sector_removal(){
 let project=Path::new(env!("CARGO_MANIFEST_DIR"));let fixed=fixture::Fixed::new();let bindings=a::nab(&fixed.bytes("evidence/appearance-bindings.nab")).unwrap();let b=&bindings[3];let(assets,plan,mut extra)=native::assets();let effect=effect(&plan,&mut extra);let index=assets.effect_records().iter().position(|v|v.effect.sprite_id==38).unwrap();let mut model=l::Model::new(true,b,b,b.observed,&assets,&plan,&effect,index,&first::create()).unwrap();let initial=model.sample(b,b.observed,&first::input()).unwrap();
 let mut rows=vec![json!({"frame":1,"due_ms":1084,"expected_ms":1169,"next_due_ms":1169,"ended":false,"opcode32":true})];let mut strip=vec![0u8;2048*1152*4];let out=project.join("target/r456-layer8-cycle-cpu");fs::create_dir_all(&out).unwrap();let mut images=Vec::new();let mut held=Vec::new();
 let mut copy=|column:usize,frame:&l::Frame,model:&l::Model<'_>|{let rgba=frame.view(model,b,b.observed).unwrap().rgba();let x=(column%4)*512;let y=(column/4)*384;for row in 0..384{strip[((y+row)*2048+x)*4..((y+row)*2048+x+512)*4].copy_from_slice(&rgba[row*512*4..(row+1)*512*4]);}images.push(fixture::png(&out.join(format!("{column:02}-frame{}.png",frame.frame)),rgba,512,384));};copy(0,&initial,&model);
 let mut missing=0;for column in 1..12{let due=model.future_due(b,b.observed).unwrap();let queued=column==11;let input=continuation(due,queued);let before=model.continuation_preview(b,b.observed,&input).unwrap();
  for which in 0..7{let mut bad=continuation(due,queued);match which{0=>bad.ordinary_path_reached=None,1=>bad.actor_counter50=None,2=>bad.post_frame_event_bit=None,3=>bad.callback.scheduler_sample_ms=None,4=>bad.callback.prior_draw_unlinked=None,5=>bad.callback.queue_before_pop=None,_=>bad.callback.dispatch_ms=Some(due-1)};assert!(model.continue_sample(b,b.observed,&bad).is_err());assert_eq!(model.continuation_preview(b,b.observed,&input).unwrap(),before);missing+=1;}
  if column==10{for which in 0..2{let mut bad=continuation(due,false);if which==0{bad.idle_queue_append_succeeds=None;}else{bad.idle_table_pointer_present=None;}assert!(model.continue_sample(b,b.observed,&bad).is_err());assert_eq!(model.future_due(b,b.observed).unwrap(),due);missing+=1;}}
  if column==1{let mut late=continuation(due,false);late.callback.dispatch_ms=Some(1300);late.callback.scheduler_sample_ms=Some(1307);let p=model.continuation_preview(b,b.observed,&late).unwrap();assert_eq!((p.frame,p.expected_ms,p.next_due_ms),(2,1254,1310));}
  let(step,frame)=model.continue_sample(b,b.observed,&input).unwrap();let expected_frame=if column==10{0}else if column==11{1}else{column+1};assert_eq!(step.frame,expected_frame);assert_eq!(step.ended,column==10);assert_eq!(step.opcode32,column==11);copy(column,&frame,&model);rows.push(json!({"frame":step.frame,"due_ms":step.due_ms,"dispatch_ms":step.dispatch_ms,"sampled_ms":step.sampled_ms,"expected_ms":step.expected_ms,"next_due_ms":step.next_due_ms,"ended":step.ended,"opcode32":step.opcode32}));held.push(frame);
 }
 assert_eq!(rows[10]["due_ms"],1934);assert_eq!(rows[10]["next_due_ms"],2017);assert_eq!(rows[11]["next_due_ms"],2102);assert!(model.continue_sample(b,b.observed,&continuation(2102,false)).is_err());images.push(fixture::png(&out.join("source-cycle-end-repeat-contact-sheet.png"),&strip,2048,1152));
 let remove=l::RemoveInputs{sector_unload_reached:Some(true),registry_actor_matches:Some(true),sector_id_range_contains_actor:Some(true),no_opcode11:Some(true),extra_draw_pointers_absent:Some(true),actor_global_pointers_differ:Some(true)};for which in 0..6{let mut q=l::RemoveInputs{..remove};match which{0=>q.sector_unload_reached=None,1=>q.registry_actor_matches=None,2=>q.sector_id_range_contains_actor=None,3=>q.no_opcode11=None,4=>q.extra_draw_pointers_absent=None,_=>q.actor_global_pointers_differ=None};assert!(model.remove_from_sector(b,b.observed,&q).is_err());assert_eq!(model.future_due(b,b.observed).unwrap(),2102);assert!(initial.view(&model,b,b.observed).is_ok());}model.remove_from_sector(b,b.observed,&remove).unwrap();assert!(model.future_due(b,b.observed).is_err());assert!(initial.view(&model,b,b.observed).is_err());for frame in held{assert!(frame.view(&model,b,b.observed).is_err());}
 fs::write(project.join("logs/continuation-20261003/r456-layer8-cycle-details.json"),serde_json::to_vec_pretty(&json!({"state":"FINITE_SOURCE_FIREPOT3_CYCLE_END0_REQUEUE_FIRST_REPEAT_AND_SECTOR_REMOVAL","rows":rows,"CPU_frames":12,"images":images,"source_repeat_action":3,"action0_invented":false,"natural_end_deletes_actor":false,"finite_continuation_budget":11,"missing_or_early_cases_preserve_state":missing,"late1307_next1310_expected1254":true,"missing_removal_cases":6,"removal_revokes_all_held_frames":true,"removal_clears_actor_timer":true,"source_record_index":index,"runtime_inputs_observed":false,"renderer_LOADED":false,"GUI":0,"screen_rounding_policy":"Explicit RGB555 floor reference; original external float thunk and RGB565 unqualified","input_pins":fixed.used.into_inner(),"extra_input_pins":extra})).unwrap()).unwrap();
}
